window.QUIZ = (window.QUIZ || []).concat([
  { id: "11-001", ch: 11, sec: "11.1", page: 209, type: "recall", level: 1,
    q: "According to the chapter, what accounts for much of the growth in U.S. irrigated area over the past two decades?",
    opts: ["Expansion of gated pipe furrow irrigation", "Conversion of pivots to subsurface drip", "New surface water storage reservoirs", "Development of sprinkler irrigation"], a: 3,
    why: "The chapter states that much of the growth in irrigated area during the past two decades came from sprinkler irrigation. Furrow, drip and storage projects are not credited with that growth.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-002", ch: 11, sec: "11.2", page: 210, type: "recall", level: 1,
    q: "On a two-nozzle impact sprinkler, which nozzle makes the sprinkler arm swing and rotate the head?",
    opts: ["The spreader nozzle", "Both nozzles share the drive equally", "The range (drive) nozzle", "The straightening vane insert"], a: 2,
    why: "The jet from the range or drive nozzle strikes the spoon on the arm and drives rotation. The spreader nozzle has a slit to break up its jet and wet the area near the sprinkler. A vane is a flow straightener, not a nozzle.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-003", ch: 11, sec: "11.2", page: 210, type: "recall", level: 1,
    q: "What is the job of the spreader nozzle on a two-nozzle impact sprinkler?",
    opts: ["Put more water close to the sprinkler", "Throw water farther than the range nozzle", "Drive the impact arm", "Reduce the total discharge of the head"], a: 0,
    why: "The spreader nozzle often has a slit that breaks up its jet so it applies water near the sprinkler, while the range nozzle throws water farther. The range nozzle drives the arm, and adding a spreader increases rather than reduces total discharge.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-004", ch: 11, sec: "11.2", page: 210, type: "concept", level: 2,
    q: "How does an impact sprinkler turn?",
    opts: ["Water pressure spins a small turbine inside the body, which turns the head at a constant slow speed through gears", "The jet strikes the arm spoon, the arm swings out against a spring, then snaps back and knocks the body around a small angle", "The reaction force of the jet leaving the nozzle spins the head continuously, the way a rotary lawn sprinkler turns", "A gear reducer driven by flow through the spreader nozzle advances the head by a fixed angle every second"], a: 1,
    why: "The book describes the jet hitting the spoon, the spring storing energy and decelerating the arm, then releasing it so the arm strikes the body and rotates it slightly. Turbine and gear drives are other designs, not the impact mechanism.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-005", ch: 11, sec: "11.2", page: 211, type: "recall", level: 1,
    q: "What do straightening vanes do when placed upstream of a sprinkler nozzle?",
    opts: ["Break the jet into finer droplets so more water lands near the head", "Reduce turbulence ahead of the nozzle and increase the distance of throw", "Limit the flow to a fixed gpm regardless of the inlet pressure", "Turn the sprinkler body a small angle each time the arm returns"], a: 1,
    why: "Vanes are small plastic inserts that calm the flow before the nozzle so the jet holds together and throws farther. Breaking the jet is the spreader's role, constant flow is the flow control nozzle's role, and rotation comes from the drive arm.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-006", ch: 11, sec: "11.2", page: 211, type: "concept", level: 2,
    q: "Why were low-pressure nozzles developed after the 1970s energy crisis?",
    opts: ["Straight bore nozzles could not be machined to match standard drill bit sizes at small diameters", "Low pressure increased the diameter of coverage of straight bore nozzles beyond the field edge", "Low-pressure nozzles let lower-rated pipe carry more water without any change in uniformity", "Straight bore nozzles at low pressure do not break up the jet, giving poor uniformity and soil compaction"], a: 3,
    why: "Lowering pump pressure cuts energy cost, but a straight bore jet at low pressure stays intact, wets a ring and packs soil. Special low-pressure nozzles were designed to break up the jet at lower pressure. Low pressure shrinks, not grows, the diameter of coverage.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-007", ch: 11, sec: "11.2", page: 212, type: "recall", level: 1,
    q: "What is the main purpose of a sprinkler riser?",
    opts: ["Reduce the pressure reaching the nozzle on the first few sprinklers", "Drain water out of the lateral between sets before it is moved", "Lift the sprinkler above the crop or structure so the jet is not blocked", "Connect the lateral to the mainline hydrant at the start of each set"], a: 2,
    why: "Risers carry water from the lateral up to the sprinkler so the canopy or structure does not interfere with the jet. Pressure reduction is done by regulators, and the mainline connection is a valve or hydrant, not a riser.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-008", ch: 11, sec: "11.2", page: 212, type: "calc", level: 1,
    q: "Sprinklers are laid out in an equilateral triangle with 50 ft between adjacent heads. What is the representative area per triangle used to compute application rate?",
    opts: ["1,083 ft²", "2,500 ft²", "1,250 ft²", "2,165 ft²"], a: 0,
    why: "The book gives A = 0.433 S² for the triangle: 0.433 × 50² = 1,082.5 ft², about 1,083 ft². 2,500 ft² is the square area S², 1,250 ft² is half of it, and 2,165 ft² uses 0.866 instead of 0.433.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-009", ch: 11, sec: "11.2", page: 212, type: "figure", level: 2,
    q: "In the triangular layout of Figure 11.3, how far apart are the laterals when sprinklers are a distance S apart?",
    opts: ["0.87 S", "1.00 S", "0.50 S", "1.50 S"], a: 0,
    why: "Figure 11.3 labels the lateral spacing L = 0.87 S. That is the height of an equilateral triangle with side S (S × sin 60°). Using S would make it a square layout.",
    eq: null, calc: null, fig: "11.3", table: null },
  { id: "11-010", ch: 11, sec: "11.3", page: 213, type: "recall", level: 1,
    q: "What is a typical discharge coefficient (Cd) for a sprinkler nozzle in Eq. 11.1?",
    opts: ["About 0.61", "About 29.82", "About 1.20", "About 0.96"], a: 3,
    why: "The book says Cd is about 0.96, depending on nozzle and sprinkler design. 0.61 is a sharp-edged orifice value, 29.82 is the unit constant in Eq. 11.1, and a coefficient above 1 is not physical here.",
    eq: "11.1", calc: "eq-11.1", fig: null, table: null },
  { id: "11-011", ch: 11, sec: "11.3", page: 213, type: "calc", level: 3,
    q: "A straight bore nozzle 7/32 in (0.219 in) inside diameter runs at 45 psi with Cd = 0.96. What is its discharge from Eq. 11.1?",
    opts: ["42.0 gpm", "9.2 gpm", "61.6 gpm", "6.5 gpm"], a: 1,
    why: "q = 29.82 × 0.96 × 0.219² × √45 = 29.82 × 0.96 × 0.0479 × 6.71 = 9.2 gpm, close to the 9.3 gpm in Table 11.1. 42.0 gpm comes from not squaring D, 61.6 gpm from using P instead of √P, and 6.5 gpm from halving the pressure.",
    eq: "11.1", calc: "eq-11.1", fig: null, table: null },
  { id: "11-012", ch: 11, sec: "11.3", page: 213, type: "calc", level: 2,
    q: "Estimate the discharge of a 1/4 in nozzle at 30 psi using Eq. 11.1 with Cd = 0.96.",
    opts: ["12.8 gpm", "53.7 gpm", "9.8 gpm", "39.2 gpm"], a: 2,
    why: "q = 29.82 × 0.96 × 0.25² × √30 = 29.82 × 0.96 × 0.0625 × 5.48 = 9.8 gpm (Table 11.1 lists 9.9 gpm). 12.8 gpm is the 50 psi value, 53.7 gpm uses P instead of √P, and 39.2 gpm forgets to square D.",
    eq: "11.1", calc: "eq-11.1", fig: null, table: null },
  { id: "11-013", ch: 11, sec: "11.3", page: 213, type: "calc", level: 2,
    q: "At constant pressure, a nozzle is replaced with one 10% larger in diameter. By how much does discharge change?",
    opts: ["Increases about 21%", "Increases about 10%", "Increases about 5%", "Increases about 33%"], a: 0,
    why: "Discharge varies with D², so the ratio is 1.10² = 1.21, a 21% increase. 10% treats flow as proportional to D, and 5% uses √D, which is how flow responds to pressure, not diameter.",
    eq: "11.1", calc: "eq-11.1-ratio", fig: null, table: null },
  { id: "11-014", ch: 11, sec: "11.3", page: 213, type: "calc", level: 2,
    q: "A sprinkler discharges 8.0 gpm at 40 psi. With the same nozzle, what will it discharge at 60 psi?",
    opts: ["12.0 gpm", "18.0 gpm", "6.5 gpm", "9.8 gpm"], a: 3,
    why: "q2 = q1 × √(P2/P1) = 8.0 × √(60/40) = 8.0 × 1.225 = 9.8 gpm. 12.0 gpm assumes flow is proportional to pressure, 18.0 gpm squares the ratio, and 6.5 gpm inverts the ratio.",
    eq: "11.1", calc: "eq-11.1-ratio", fig: null, table: null },
  { id: "11-015", ch: 11, sec: "11.3", page: 213, type: "calc", level: 3,
    q: "A sprinkler has a 32/128 in nozzle. To raise its discharge 25% at the same pressure, what is the smallest standard size (in 128ths) that will do it?",
    opts: ["34/128 in", "36/128 in", "40/128 in", "50/128 in"], a: 1,
    why: "Flow scales with D², so D2 = 32 × √1.25 = 35.8/128 in. The next size up is 36/128 (9/32 in). 34/128 is too small, 40/128 is a 25% larger diameter (56% more flow), and 50/128 comes from multiplying by 1.25².",
    eq: "11.1", calc: "eq-11.1-ratio", fig: null, table: null },
  { id: "11-016", ch: 11, sec: "11.3", page: 213, type: "concept", level: 2,
    q: "With the same nozzle, how much must pressure increase to double the sprinkler discharge?",
    opts: ["Twice the original pressure", "About 1.4 times the original pressure", "Four times the original pressure", "Eight times the original pressure"], a: 2,
    why: "Discharge varies with √P, so doubling flow needs (2)² = 4 times the pressure. That is why changing nozzle size, not pressure, is the practical way to change flow a lot.",
    eq: "11.1", calc: "eq-11.1-ratio", fig: null, table: null },
  { id: "11-017", ch: 11, sec: "11.3", page: 213, type: "concept", level: 1,
    q: "Example 11.1 compares a 20% larger nozzle with 20% more pressure. Which gives more flow and why?",
    opts: ["The higher pressure, because flow varies with P²", "They give the same flow because both are 20% changes", "The larger nozzle, because flow varies with D² but only with √P", "The higher pressure, because a larger nozzle lowers the discharge coefficient"], a: 2,
    why: "From Eq. 11.1, 1.2² = 1.44 gives 44% more flow from the larger nozzle, while √1.2 = 1.095 gives only about 10% more from the higher pressure.",
    eq: "11.1", calc: "eq-11.1-ratio", fig: null, table: null },
  { id: "11-018", ch: 11, sec: "11.3", page: 213, type: "recall", level: 1,
    q: "A manufacturer sizes nozzles in 128ths of an inch. What diameter is a size 28 nozzle?",
    opts: ["7/16 in", "0.28 in", "1/4 in", "7/32 in"], a: 3,
    why: "28/128 = 7/32 in (0.219 in), which is the nozzle in the book's side-roll example. Reading 28 as 64ths gives 7/16 in, and 0.28 in treats the size as hundredths.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-019", ch: 11, sec: "11.3", page: 214, type: "recall", level: 1,
    q: "For agricultural sprinklers, the diameter of coverage is usually taken as the farthest distance where the application rate equals what value?",
    opts: ["0.10 in/hr", "0.01 in/hr", "0.001 in/hr", "Half the average rate"], a: 1,
    why: "The book defines the diameter of coverage for agricultural sprinklers as the maximum radial extent where the rate is 0.01 in/hr, usually measured indoors with no wind.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-020", ch: 11, sec: "11.3", page: 214, type: "recall", level: 2,
    q: "The diameters of coverage in Table 11.2 apply to which sprinkler condition?",
    opts: ["Brass impact sprinklers with a 23° range nozzle angle, measured indoors without wind", "Low-angle 7° impact sprinklers measured outdoors in an average 5 mph wind", "Spray heads hung on center pivot drops a few feet above the crop canopy", "Any impact sprinkler fitted with a straightening vane, at any trajectory angle"], a: 0,
    why: "Table 11.2 is for impact sprinklers with straight bore nozzles where the range nozzle jet leaves at 23° above horizontal, with wetted diameter usually measured indoors with no wind. Other designs need the manufacturer's data.",
    eq: null, calc: null, fig: null, table: "11.2" },
  { id: "11-021", ch: 11, sec: "11.3", page: 214, type: "recall", level: 2,
    q: "By how much can straightening vanes increase the diameter of coverage?",
    opts: ["From about 1% to 2% at most", "From about 5% to as much as 20%", "About 50% in most heads", "No change in diameter, only in uniformity"], a: 1,
    why: "The book reports that vanes increase the diameter of coverage 5% to 20% depending on the head and nozzle, because they reduce turbulence in the barrel.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-022", ch: 11, sec: "11.3", page: 216, type: "concept", level: 2,
    q: "Why do sprinklers with straightening vanes usually need a higher minimum operating pressure?",
    opts: ["Vanes reduce jet breakup, so at low pressure they tend to form a doughnut pattern", "Vanes add friction in the barrel that must be overcome before the head will rotate", "Vanes collect debris and clog unless the pressure is high enough to flush them", "Vanes shrink the effective nozzle diameter, so more pressure is needed for the same flow"], a: 0,
    why: "Vanes keep the jet intact for more throw. At low pressure an intact jet already wets mainly a ring, so vanes make the doughnut worse. A higher minimum pressure prevents that.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-023", ch: 11, sec: "11.3", page: 214, type: "concept", level: 2,
    q: "What happens to a sprinkler's distribution when it operates well above its rated pressure?",
    opts: ["The jet stays intact and lands mostly in a ring near the edge, leaving the area around the head dry", "The wetted diameter keeps increasing with pressure, spreading the same water over a much larger area", "The jet breaks into small drops that land near the head, shrinking the wetted diameter and raising the rate close in", "Discharge drops because the nozzle chokes, so the whole pattern gets lighter but keeps the same shape"], a: 2,
    why: "Excess pressure atomizes the jet, and small drops decelerate fast and land close to the head. That reduces the wetted diameter and piles water near the sprinkler. The ring pattern is the low-pressure symptom.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-024", ch: 11, sec: "11.3", page: 215, type: "figure", level: 1,
    q: "In the depth distribution panel of Figure 11.5, what shape does the curve for too-low pressure have?",
    opts: ["A tall dome centered on the sprinkler that falls off quickly with distance", "A nearly flat, elliptical profile that tapers smoothly at the outer edge", "A single peak at one edge only, with the far side receiving no water", "A doughnut, with little water near the sprinkler and peaks toward the edge"], a: 3,
    why: "The curve labeled pressure too low dips at the sprinkler and rises toward the outer wetted area, the doughnut shape. The tall dome is the too-high pressure curve, and the flatter elliptical curve is the acceptable range.",
    eq: null, calc: null, fig: "11.5", table: null },
  { id: "11-025", ch: 11, sec: "11.3", page: 216, type: "figure", level: 2,
    q: "In the top panel of Figure 11.6, what happens where sprinkler spacing is stretched from SL to 1.5 × SL?",
    opts: ["The patterns stop overlapping and the overlapped depth dips between those sprinklers", "The overlapped depth rises between those sprinklers because each pattern is larger", "Nothing changes, because each sprinkler applies the same pattern at any spacing", "The depth becomes uniform along the lateral because there is less double coverage"], a: 0,
    why: "The figure marks a no-overlap gap where spacing is 1.5 × SL, and the overlapped depth line drops there. Depth at a point is the sum from all sprinklers reaching it, so a gap means less water.",
    eq: null, calc: null, fig: "11.6", table: null },
  { id: "11-026", ch: 11, sec: "11.3", page: 216, type: "figure", level: 3,
    q: "Figure 11.6 compares 40 ft × 60 ft and 50 ft × 70 ft layouts designed for the same 3 in depth. What does the wider layout show?",
    opts: ["A flatter, more uniform surface than the 40 ft × 60 ft layout because fewer heads overlap", "A pronounced peak in the middle of the representative area with lower depths around it", "A dry center with the highest depths in the corners near each sprinkler", "The same uniformity as the closer layout because the design depth is the same 3 in"], a: 1,
    why: "The 50 ft × 70 ft surface rises to a dome near 4 in in the middle while edges fall below the target, which the book calls a poorer distribution. The closer spacing is flatter around the 3 in target.",
    eq: null, calc: null, fig: "11.6", table: null },
  { id: "11-027", ch: 11, sec: "11.3", page: 216, type: "calc", level: 2,
    q: "A layout is designed to apply 3 in in 10 hr on a 50 ft × 70 ft rectangular spacing. What sprinkler discharge is needed?",
    opts: ["7.5 gpm", "109 gpm", "1.1 gpm", "10.9 gpm"], a: 3,
    why: "Required rate is 3 in ÷ 10 hr = 0.30 in/hr. From Eq. 11.2, q = Ar × SL × Sm ÷ 96.3 = 0.30 × 3,500 ÷ 96.3 = 10.9 gpm, the value in the book. 7.5 gpm is for the 40 ft × 60 ft spacing, 109 gpm uses 3 in/hr, and 1.1 gpm drops a factor of 10.",
    eq: "11.2", calc: "eq-11.2-11.3", fig: null, table: null },
  { id: "11-028", ch: 11, sec: "11.3", page: 217, type: "concept", level: 2,
    q: "Why does a crosswind narrow a sprinkler's wetted pattern in the direction perpendicular to the wind?",
    opts: ["Wind blowing into the nozzle raises the pressure on the upwind side and shortens the throw downwind", "Wind slows the rotation of the sprinkler so it spends less time throwing water across the wind", "Drops thrown across the wind are bent downwind, and the jet breaks into smaller drops that travel less far", "Wind evaporates nearly all of the water thrown across it before the drops can reach the ground"], a: 2,
    why: "Droplets thrown perpendicular to the wind follow a curved path that turns downwind, and the crosswind breaks the jet into smaller drops with shorter range. The pattern ends up displaced downwind and narrower across the wind.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-029", ch: 11, sec: "11.3", page: 217, type: "figure", level: 3,
    q: "According to Figure 11.8, which lateral orientation keeps adequate overlap in wind, and why?",
    opts: ["Parallel to the wind, because each pattern stretches downwind toward the next lateral and fills the gap", "Perpendicular to the wind, because the narrowed width of each pattern falls along the lateral where heads are closest", "Parallel to the wind, because fewer laterals are needed and overlap between laterals is not affected", "Either orientation, because the wind narrows and stretches the patterns equally in both directions"], a: 1,
    why: "With laterals perpendicular to the wind, the narrowing occurs along the lateral where spacing SL is small, while the stretched dimension spans the wider Sm. Parallel laterals leave a dry strip between laterals.",
    eq: null, calc: null, fig: "11.8", table: null },
  { id: "11-030", ch: 11, sec: "11.3", page: 218, type: "table", level: 1,
    q: "From Table 11.3, what is the maximum sprinkler spacing along a lateral for a rectangular layout with average wind of 8 to 12 mph?",
    opts: ["45% of the diameter of coverage", "50% of the diameter of coverage", "40% of the diameter of coverage", "60% of the diameter of coverage"], a: 2,
    why: "Table 11.3 lists 50%, 45% and 40% along the lateral for winds of 0 to 3, 4 to 7 and 8 to 12 mph. 60% is the between-lateral limit for all rectangular wind classes.",
    eq: null, calc: "tab-11.3", fig: null, table: "11.3" },
  { id: "11-031", ch: 11, sec: "11.3", page: 218, type: "table", level: 2,
    q: "From Table 11.3 and its footnote, how is spacing set for an equilateral triangle layout in calm conditions (0 to 3 mph)?",
    opts: ["Sprinklers up to 60% of the diameter apart, with laterals 0.866 times that spacing apart", "Sprinklers up to 50% of the diameter apart, with laterals 60% of the diameter apart", "Sprinklers and laterals both set at 55% of the diameter of coverage in calm air", "Sprinklers up to 60% of the diameter apart, with laterals 1.5 times that spacing apart"], a: 0,
    why: "The triangle row for 0 to 3 mph gives 60% of the diameter, and the footnote sets lateral spacing at 0.866 × sprinkler spacing so the triangle stays equilateral.",
    eq: null, calc: "tab-11.3", fig: null, table: "11.3" },
  { id: "11-032", ch: 11, sec: "11.3", page: 218, type: "calc", level: 2,
    q: "Sprinklers on a rectangular layout have a 102 ft diameter of coverage and the average wind is 6 mph. What are the maximum spacings along and between laterals?",
    opts: ["51.0 ft along and 61.2 ft between", "40.8 ft along and 61.2 ft between", "61.2 ft along and 45.9 ft between", "45.9 ft along and 61.2 ft between"], a: 3,
    why: "At 4 to 7 mph Table 11.3 gives 45% along and 60% between: 0.45 × 102 = 45.9 ft and 0.60 × 102 = 61.2 ft. 51.0 ft uses the calm 50% class, 40.8 ft the 8 to 12 mph class, and 61.2 ft along with 45.9 ft between swaps the two directions.",
    eq: null, calc: "tab-11.3", fig: null, table: "11.3" },
  { id: "11-033", ch: 11, sec: "11.3", page: 218, type: "calc", level: 3,
    q: "A rectangular layout has sprinklers 40 ft apart and laterals 50 ft apart in an average 9 mph wind. What diameter of coverage is needed?",
    opts: ["100 ft", "83 ft", "89 ft", "111 ft"], a: 0,
    why: "At 8 to 12 mph the limits are 40% along and 60% between. Needed diameter is the larger of 40 ÷ 0.40 = 100 ft and 50 ÷ 0.60 = 83 ft, so 100 ft. 83 ft checks only the lateral spacing, 89 ft uses the 45% class, and 111 ft divides 50 by 0.45.",
    eq: null, calc: "tab-11.3", fig: null, table: "11.3" },
  { id: "11-034", ch: 11, sec: "11.3", page: 218, type: "calc", level: 3,
    q: "Sprinklers with a 100 ft diameter of coverage will be set in an equilateral triangle. Average wind is 5 mph. What are the maximum sprinkler spacing and the matching lateral spacing?",
    opts: ["55 ft between sprinklers and 60 ft between laterals", "55 ft between sprinklers and 47.6 ft between laterals", "60 ft between sprinklers and 52 ft between laterals", "50 ft between sprinklers and 43.3 ft between laterals"], a: 1,
    why: "The triangle limit at 4 to 7 mph is 55%, so S = 0.55 × 100 = 55 ft and lateral spacing = 0.866 × 55 = 47.6 ft. 60 ft is the calm class, 50 ft is the 8 to 12 mph class, and 60 ft between laterals applies only to rectangular layouts.",
    eq: null, calc: "tab-11.3", fig: null, table: "11.3" },
  { id: "11-035", ch: 11, sec: "11.3", page: 215, type: "table", level: 1,
    q: "From Table 11.2, what is the diameter of coverage of a 3/16 in nozzle at 50 psi?",
    opts: ["96 ft", "107 ft", "100 ft", "91 ft"], a: 2,
    why: "Table 11.2 lists 100 ft for 3/16 in at 50 psi, the value used in Example 11.3. 96 ft is 3/16 in at 40 psi, 107 ft is 13/64 in at 50 psi, and 91 ft is 3/16 in at 30 psi.",
    eq: null, calc: "tab-11.1-11.2", fig: null, table: "11.2" },
  { id: "11-036", ch: 11, sec: "11.3", page: 215, type: "table", level: 2,
    q: "Using Table 11.2, what is the smallest nozzle that gives at least a 110 ft diameter of coverage at 50 psi?",
    opts: ["13/64 in", "3/16 in", "15/64 in", "7/32 in"], a: 3,
    why: "At 50 psi Table 11.2 gives 100 ft for 3/16 in, 107 ft for 13/64 in, 110 ft for 7/32 in and 112 ft for 15/64 in. The first size reaching 110 ft is 7/32 in.",
    eq: null, calc: "tab-11.1-11.2", fig: null, table: "11.2" },
  { id: "11-037", ch: 11, sec: "11.3", page: 214, type: "table", level: 1,
    q: "From Table 11.1, what is the discharge of a 5/32 in straight bore nozzle at 50 psi?",
    opts: ["4.5 gpm", "5.0 gpm", "6.0 gpm", "7.2 gpm"], a: 1,
    why: "Table 11.1 lists 5.0 gpm for 5/32 in at 50 psi, the value used in Example 11.4. 4.5 gpm is the 40 psi value, 6.0 gpm is 11/64 in, and 7.2 gpm is 3/16 in at 50 psi.",
    eq: null, calc: "tab-11.1-11.2", fig: null, table: "11.1" },
  { id: "11-038", ch: 11, sec: "11.3", page: 214, type: "table", level: 2,
    q: "An impact sprinkler has an 11/64 in range nozzle and a 3/32 in spreader nozzle at 50 psi. From Table 11.1, what is the total discharge?",
    opts: ["6.0 gpm", "1.8 gpm", "7.8 gpm", "7.2 gpm"], a: 2,
    why: "Total discharge is the sum of both nozzles at that pressure: 6.0 + 1.8 = 7.8 gpm. 6.0 gpm counts only the range nozzle, 1.8 gpm only the spreader, and 7.2 gpm is a 3/16 in nozzle.",
    eq: null, calc: "tab-11.1-11.2", fig: null, table: "11.1" },
  { id: "11-039", ch: 11, sec: "11.3", page: 218, type: "concept", level: 3,
    q: "Why does the effective water input to the rectangular representative area SL × Sm equal the discharge of one sprinkler?",
    opts: ["Only the sprinkler nearest the center waters the area, and water from the corner sprinklers falls outside it", "Half of the flow from each of two adjacent sprinklers falls in the area, and the other two sprinklers miss it", "The area receives the full flow of all four corner sprinklers, so its input is four times one discharge", "Each corner sprinkler puts one-fourth of its flow into the area, and overthrow is offset by water thrown in by neighbors"], a: 3,
    why: "A quarter of the flow from each of four sprinklers lands in the rectangle, which sums to one sprinkler's discharge. Water leaving the rectangle is replaced by water from adjacent sprinklers, so Ar = 96.3 q ÷ (SL Sm).",
    eq: "11.2", calc: "eq-11.2-11.3", fig: null, table: null },
  { id: "11-040", ch: 11, sec: "11.3", page: 219, type: "concept", level: 3,
    q: "Where does the constant 111.2 in the triangular application rate (Eq. 11.3) come from?",
    opts: ["96.3 ÷ (2 × 0.433), since half a sprinkler's flow falls on 0.433 S²", "96.3 × 0.866 ÷ 0.75, a correction for wind and triangle height", "96.3 + 15, an allowance for the extra heads a triangle needs", "96.3 × 1.155, the ratio of hexagon area to square area"], a: 0,
    why: "Each sprinkler waters six surrounding triangles, so each triangle gets half a sprinkler's discharge over an area of 0.433 S². Ar = 96.3 × (q/2) ÷ (0.433 S²) = 111.2 q ÷ S².",
    eq: "11.3", calc: "eq-11.2-11.3", fig: null, table: null },
  { id: "11-041", ch: 11, sec: "11.3", page: 218, type: "calc", level: 1,
    q: "Sprinklers discharging 9.0 gpm are spaced 40 ft along the lateral and 50 ft between laterals. What is the application rate?",
    opts: ["0.36 in/hr", "0.50 in/hr", "4.33 in/hr", "0.43 in/hr"], a: 3,
    why: "Ar = 96.3 × 9.0 ÷ (40 × 50) = 866.7 ÷ 2,000 = 0.43 in/hr. 0.36 in/hr uses a 40 ft × 60 ft area, 0.50 in/hr uses the triangle constant 111.2, and 4.33 in/hr is a decimal slip.",
    eq: "11.2", calc: "eq-11.2-11.3", fig: null, table: null },
  { id: "11-042", ch: 11, sec: "11.3", page: 219, type: "calc", level: 2,
    q: "Sprinklers on a 30 ft equilateral triangle each discharge 4.2 gpm. What is the application rate?",
    opts: ["0.45 in/hr", "0.26 in/hr", "0.52 in/hr", "1.04 in/hr"], a: 2,
    why: "Eq. 11.3: Ar = 111.2 × 4.2 ÷ 30² = 467 ÷ 900 = 0.52 in/hr. 0.45 in/hr uses the rectangular 96.3 constant, 0.26 in/hr halves the answer, and 1.04 in/hr doubles it.",
    eq: "11.3", calc: "eq-11.2-11.3", fig: null, table: null },
  { id: "11-043", ch: 11, sec: "11.3", page: 219, type: "calc", level: 1,
    q: "A system applies 0.35 in/hr and water is on for 11 hr of a 12 hr set. What gross depth is applied?",
    opts: ["4.20 in", "3.85 in", "2.89 in", "0.03 in"], a: 1,
    why: "Eq. 11.4: dg = Ar × To = 0.35 × 11 = 3.85 in. 4.20 in uses the 12 hr set time instead of the 11 hr operating time, 2.89 in applies a 75% efficiency (that would be net, not gross), and 0.03 in divides instead of multiplying.",
    eq: "11.4", calc: "eq-11.4", fig: null, table: null },
  { id: "11-044", ch: 11, sec: "11.3", page: 219, type: "calc", level: 2,
    q: "Sprinklers discharge 10 gpm on a 40 ft × 60 ft spacing. How long must the system run to apply 3 in gross?",
    opts: ["7.5 hr", "10.0 hr", "5.6 hr", "1.2 hr"], a: 0,
    why: "Ar = 96.3 × 10 ÷ 2,400 = 0.40 in/hr, so To = 3 ÷ 0.40 = 7.5 hr. 10.0 hr is the time for 3 in net at 75% efficiency, 5.6 hr multiplies by 0.75 instead of dividing, and 1.2 hr multiplies rate by depth.",
    eq: "11.4", calc: "eq-11.4", fig: null, table: null },
  { id: "11-045", ch: 11, sec: "11.3", page: 219, type: "calc", level: 3,
    q: "Sprinklers discharge 10 gpm on a 40 ft × 60 ft spacing and application efficiency is 75%. How long must the system run to deliver 3 in net to the crop?",
    opts: ["7.5 hr", "5.6 hr", "10.0 hr", "13.3 hr"], a: 2,
    why: "Gross depth = 3 ÷ 0.75 = 4.0 in. Ar = 96.3 × 10 ÷ 2,400 = 0.40 in/hr, so To = 4.0 ÷ 0.40 = 10.0 hr. 7.5 hr treats 3 in as gross, 5.6 hr multiplies by 0.75, and 13.3 hr divides by 0.75 twice.",
    eq: "11.4", calc: "eq-11.4", fig: null, table: null },
  { id: "11-046", ch: 11, sec: "11.3", page: 219, type: "concept", level: 1,
    q: "The depth from Eq. 11.4 (dg = Ar × To) is gross. What must be done to find the water available to the crop?",
    opts: ["Multiply by the application efficiency", "Divide by the application efficiency", "Add the expected effective rainfall", "Multiply by the multiple outlet factor"], a: 0,
    why: "Eq. 11.4 gives water leaving the nozzles. Some is lost to drift, evaporation, runoff or deep percolation, so net depth = gross × application efficiency. Dividing would make net larger than gross.",
    eq: "11.4", calc: "eq-11.4", fig: null, table: null },
  { id: "11-047", ch: 11, sec: "11.3", page: 219, type: "table", level: 1,
    q: "From Table 11.4, what is the maximum recommended application rate for a medium-textured soil (such as silt loam) with an unprotected surface on a 0 to 5% slope?",
    opts: ["0.50 to 0.75 in/hr", "0.10 to 0.25 in/hr", "0.50 to 0.95 in/hr", "0.25 to 0.50 in/hr"], a: 3,
    why: "The medium column for unprotected soil at 0 to 5% gives 0.25 to 0.50 in/hr, used in Example 11.3. 0.50 to 0.75 is coarse, 0.10 to 0.25 is fine, and 0.50 to 0.95 is medium with turf or heavy residue.",
    eq: null, calc: "tab-11.4", fig: null, table: "11.4" },
  { id: "11-048", ch: 11, sec: "11.3", page: 219, type: "table", level: 1,
    q: "From Table 11.4, what is the maximum recommended application rate for a fine-textured soil under turfgrass or heavy residue on a 0 to 5% slope?",
    opts: ["0.10 to 0.25 in/hr", "0.15 to 0.35 in/hr", "0.50 to 0.95 in/hr", "0.85 to 1.30 in/hr"], a: 1,
    why: "The fine column with turf or heavy residue at 0 to 5% gives 0.15 to 0.35 in/hr. 0.10 to 0.25 is the same soil unprotected, 0.50 to 0.95 is medium with cover, and 0.85 to 1.30 is coarse with cover.",
    eq: null, calc: "tab-11.4", fig: null, table: "11.4" },
  { id: "11-049", ch: 11, sec: "11.3", page: 219, type: "table", level: 2,
    q: "From Table 11.4, what is the maximum recommended application rate for a sandy soil with an unprotected surface on a 10% slope?",
    opts: ["0.40 to 0.60 in/hr", "0.50 to 0.75 in/hr", "0.30 to 0.45 in/hr", "0.15 to 0.30 in/hr"], a: 2,
    why: "A 10% slope falls in the 9 to 12% row, and the coarse unprotected column gives 0.30 to 0.45 in/hr. 0.40 to 0.60 is the 6 to 8% row, 0.50 to 0.75 is 0 to 5%, and 0.15 to 0.30 is the medium column at 9 to 12%.",
    eq: null, calc: "tab-11.4", fig: null, table: "11.4" },
  { id: "11-050", ch: 11, sec: "11.3", page: 219, type: "scenario", level: 2,
    q: "A no-till grower with heavy corn residue on a medium-textured soil at 3% slope asks whether he must stay under the 0.25 to 0.50 in/hr bare-soil limit in Table 11.4. What do you tell him?",
    opts: ["No. The table values are fixed limits that apply whatever the residue or tillage", "Yes, the limit can be raised, since residue that improves infiltration allows a higher rate", "The limit should be lowered, because residue seals the surface and slows intake", "Residue has no effect on intake, so use the fine-texture column to be safe"], a: 1,
    why: "Table 11.4 values are general guidelines. The book says to adjust them upward where practices such as adequate residue improve infiltration, and downward where infiltration is reduced. The turf or heavy residue row for medium soil at 0 to 5% gives 0.50 to 0.95 in/hr.",
    eq: null, calc: "tab-11.4", fig: null, table: "11.4" },
  { id: "11-051", ch: 11, sec: "11.3", page: 220, type: "calc", level: 3,
    q: "A rectangular layout of 50 ft × 60 ft will run at 55 psi with brass impact sprinklers in a 5 mph average wind. Using Tables 11.1 to 11.3, what is the smallest nozzle that gives adequate overlap, and what is the application rate?",
    opts: ["7/32 in at about 0.33 in/hr", "3/16 in at about 0.24 in/hr", "13/64 in at about 0.29 in/hr", "15/64 in at about 0.38 in/hr"], a: 0,
    why: "Needed diameter is the larger of 50 ÷ 0.45 = 111 ft and 60 ÷ 0.60 = 100 ft. At 55 psi, 13/64 in reaches 109 ft and 7/32 in reaches 113 ft, so 7/32 in is the smallest. It discharges 10.3 gpm, so Ar = 96.3 × 10.3 ÷ 3,000 = 0.33 in/hr. 3/16 in (101 ft) and 13/64 in (109 ft) fall short of 111 ft, and 15/64 in is larger than needed.",
    eq: "11.2", calc: "proc-nozzle-select", fig: null, table: null },
  { id: "11-052", ch: 11, sec: "11.3", page: 220, type: "scenario", level: 2,
    q: "A grower says: \"My hand-move is on 40 by 60 ft spacing on bare silt loam with about 2% slope. I want to swap my 3/16 in nozzles for 1/4 in at 50 psi so I can finish sets faster.\" What do you tell him?",
    opts: ["About 0.29 in/hr, well inside the 0.25 to 0.50 in/hr limit, so the swap is fine for bare silt loam", "The rate stays the same because the spacing has not changed, so only the set time gets shorter", "About 0.14 in/hr, because the bigger nozzle spreads the water over a larger wetted diameter", "About 0.51 in/hr, just above the 0.25 to 0.50 in/hr limit for bare silt loam, so expect ponding and runoff"], a: 3,
    why: "A 1/4 in nozzle at 50 psi gives 12.8 gpm (Table 11.1), so Ar = 96.3 × 12.8 ÷ 2,400 = 0.51 in/hr. Table 11.4 allows 0.25 to 0.50 in/hr for unprotected medium soil at 0 to 5%. 0.29 in/hr is the rate with the current 3/16 in nozzles.",
    eq: "11.2", calc: "eq-11.2-11.3", fig: null, table: "11.4" },
  { id: "11-053", ch: 11, sec: "11.3", page: 219, type: "scenario", level: 3,
    q: "A landscape client has heads on a 30 ft triangle putting out 4.2 gpm each on a bare silt loam slope of 8%. They see runoff at the bottom of the bank. Which number explains it?",
    opts: ["The 0.45 in/hr rate is inside the 0.25 to 0.50 in/hr limit, so look for a leak", "The 0.52 in/hr rate is above the 0.20 to 0.40 in/hr limit for that soil and slope", "The 30 ft spacing is wider than 60% of the diameter of coverage for these heads", "The nozzle pressure is too high for 4.2 gpm and the water is atomizing on the bank"], a: 1,
    why: "Eq. 11.3 gives 111.2 × 4.2 ÷ 900 = 0.52 in/hr. Table 11.4 for unprotected medium soil at 6 to 8% slope allows 0.20 to 0.40 in/hr, so the rate exceeds infiltration. 0.45 in/hr wrongly uses the rectangular constant and the 0 to 5% row.",
    eq: "11.3", calc: "eq-11.2-11.3", fig: null, table: "11.4" },
  { id: "11-054", ch: 11, sec: "11.3", page: 217, type: "scenario", level: 2,
    q: "A grower is laying out a new solid-set block where summer winds blow steadily from the southwest. He asks which way to run the laterals. What do you advise?",
    opts: ["Run the laterals perpendicular to the wind, northwest to southeast", "Run the laterals parallel to the wind, southwest to northeast", "Direction does not matter if spacing meets Table 11.3 in calm air", "Run the laterals diagonally, east to west, to split the difference"], a: 0,
    why: "Wind narrows the pattern across its direction. Laterals perpendicular to the wind put that narrowing along the lateral, where sprinklers are close together, giving better overlap and a cheaper system. Parallel laterals leave dry strips between them.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-055", ch: 11, sec: "11.3", page: 216, type: "scenario", level: 3,
    q: "A grower says: \"I started moving my wheel line 70 ft instead of 50 ft to save a set each day. Now I see stress streaks between sets.\" His sprinklers have about a 100 ft diameter of coverage. What is the problem?",
    opts: ["The sprinklers now apply too much water at each set, which drowns the crop next to the lateral", "Moving the line farther each set lowers the pressure at the far end, which starves those heads", "The streaks come from wind alone, since spacing does not change how much water lands between sets", "The 70 ft move exceeds the 60 ft limit (60% of 100 ft), so overlap between sets is inadequate"], a: 3,
    why: "Table 11.3 limits rectangular lateral spacing to 60% of the diameter of coverage, here 60 ft. At 70 ft the patterns barely overlap and the middle between sets gets too little water, as in Figure 11.6. Stretching spacing to cut costs is the mistake the book warns about.",
    eq: null, calc: "tab-11.3", fig: null, table: "11.3" },
  { id: "11-056", ch: 11, sec: "11.3", page: 216, type: "scenario", level: 2,
    q: "A grower's sprinklers are rated for 45 to 60 psi, but a gauge at the nozzle reads 25 psi. He says the ground right around each head stays dry. What is happening?",
    opts: ["Pressure is too high, so the water atomizes near the head and blows away before landing", "The nozzles are worn oversize, so the water drops out of the jet before it reaches the head", "Pressure is too low, so the jet stays intact and wets mainly a ring, a doughnut pattern", "The sprinklers are spaced too close, so neighboring jets knock each other down near the heads"], a: 2,
    why: "Below its range, the jet stays intact and lands mostly near the outer edge, leaving a dry center. Too-high pressure does the opposite, piling water near the head. Raise pressure into the manufacturer's range.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-057", ch: 11, sec: "11.3", page: 216, type: "scenario", level: 2,
    q: "A grower turned up his pump and now sees a fine mist drifting off the field and wet circles that look smaller. What do you tell him?",
    opts: ["Pressure is above the nozzle range, so the jet breaks into small drops that drift and land close in. Bring pressure back into range", "Mist means the nozzles are too small for the flow. Replace them with the next larger size to bring the drop size back up", "Smaller wet circles are normal at high pressure and actually improve uniformity, so keep running at the new pressure", "Add straightening vanes to the nozzles so the jet breaks up more and the mist settles closer to each sprinkler"], a: 0,
    why: "Too much pressure atomizes the jet. Small drops decelerate quickly, so the wetted diameter shrinks and drift and evaporation rise. Vanes would reduce breakup, not increase it, but the root fix is correct pressure.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-058", ch: 11, sec: "11.3", page: 218, type: "scenario", level: 3,
    q: "A grower in a windy valley (average 9 mph) has a rectangular layout of 40 ft × 60 ft with sprinklers whose diameter of coverage is 95 ft. Does it meet Table 11.3?",
    opts: ["Yes. The limits are 43 ft along and 57 ft between laterals, so it just meets them", "Yes. Only the 60 ft lateral spacing is checked, and it is within 60% of 95 ft", "No, but only the 40 ft spacing along the lateral fails, while the 60 ft spacing passes", "No. The limits are 38 ft along and 57 ft between laterals, so both spacings are too wide"], a: 3,
    why: "At 8 to 12 mph the limits are 40% along (0.40 × 95 = 38 ft) and 60% between (0.60 × 95 = 57 ft). The 40 ft and 60 ft spacings both exceed them. 43 ft is the 4 to 7 mph limit along the lateral.",
    eq: null, calc: "tab-11.3", fig: null, table: "11.3" },
  { id: "11-059", ch: 11, sec: "11.3", page: 218, type: "scenario", level: 3,
    q: "A dealer quoted a grower impact sprinklers with 11/64 in × 3/32 in nozzles at 50 psi, spaced 40 ft on the lateral with laterals 60 ft apart. Average wind is 5 mph. Will coverage be acceptable?",
    opts: ["Yes. The 95 ft diameter allows 43 ft along and 66 ft between laterals, so both spacings pass with room to spare", "Not quite. 95 ft of coverage allows 43 ft along but only 57 ft between laterals, so 60 ft just fails", "No. The 95 ft diameter allows only 38 ft along the lateral, so the 40 ft spacing fails while the 60 ft spacing passes", "Yes. The 3/32 in spreader nozzle adds its own coverage, so the two nozzles together easily cover a 40 by 60 ft layout"], a: 1,
    why: "Table 11.2 gives 95 ft for the 11/64 in range nozzle at 50 psi. At 4 to 7 mph, Table 11.3 allows 0.45 × 95 = 43 ft along and 0.60 × 95 = 57 ft between laterals, so 60 ft just fails, as in Example 11.2, where a straightening vane is suggested. 38 ft is the 8 to 12 mph limit, and the spreader nozzle does not extend the diameter of coverage.",
    eq: null, calc: "tab-11.3", fig: null, table: "11.3" },
  { id: "11-060", ch: 11, sec: "11.3", page: 219, type: "scenario", level: 2,
    q: "A grower runs 11 hr of every 12 hr set and his sprinklers apply 0.40 in/hr. With a 75% application efficiency, how much water reaches the crop root zone each set?",
    opts: ["4.4 in", "4.8 in", "3.3 in", "3.6 in"], a: 2,
    why: "Gross depth = 0.40 × 11 = 4.4 in. Net = 4.4 × 0.75 = 3.3 in. 4.4 in is gross, 4.8 in uses the full 12 hr set, and 3.6 in is 0.75 × 4.8.",
    eq: "11.4", calc: "eq-11.4", fig: null, table: null },
  { id: "11-061", ch: 11, sec: "11.4", page: 220, type: "recall", level: 1,
    q: "What is the general limit on variation of sprinkler discharge along a lateral?",
    opts: ["Less than 20% of the average discharge", "Less than 5% of the average discharge", "Less than 25% of the average discharge", "Less than 10% of the average discharge"], a: 3,
    why: "Discharge from the highest to lowest sprinkler should differ by less than 10% of the average. The 20% figure is the matching limit on pressure variation.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-062", ch: 11, sec: "11.4", page: 220, type: "concept", level: 3,
    q: "Why does a 10% limit on discharge variation translate into about a 20% limit on pressure variation?",
    opts: ["Pressure losses along a lateral are always about twice the losses in discharge", "Friction loss doubles from the inlet to the distal end of any lateral on level ground", "Discharge varies with √P, so a 1.1 discharge ratio needs a 1.1² = 1.21 pressure ratio", "Discharge varies with P², so pressure can vary only half as much as discharge"], a: 2,
    why: "From Eq. 11.1, q is proportional to √P. Squaring the allowed 1.1 discharge ratio gives about 1.2, a 20% pressure variation.",
    eq: "11.1", calc: null, fig: null, table: null },
  { id: "11-063", ch: 11, sec: "11.4", page: 222, type: "recall", level: 1,
    q: "What pressure change is caused by a 10 ft change in elevation?",
    opts: ["2.31 psi", "4.3 psi", "10 psi", "23.1 psi"], a: 1,
    why: "Pressure in psi equals head in feet divided by 2.31, so 10 ft ÷ 2.31 = 4.3 psi. 2.31 is the conversion factor itself, and 23.1 multiplies instead of dividing.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-064", ch: 11, sec: "11.4", page: 222, type: "calc", level: 1,
    q: "A lateral runs 30 ft uphill from inlet to distal end. What pressure is lost to elevation alone?",
    opts: ["13.0 psi", "69.3 psi", "4.3 psi", "30.0 psi"], a: 0,
    why: "30 ft ÷ 2.31 ft/psi = 13.0 psi. 69.3 psi multiplies by 2.31, 4.3 psi is the loss for 10 ft, and 30.0 psi treats feet as psi.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-065", ch: 11, sec: "11.4", page: 221, type: "figure", level: 2,
    q: "In Figure 11.9, about how far from the inlet does the lateral pressure equal the average pressure?",
    opts: ["About 400 ft", "About 200 ft", "About 600 ft", "About 300 ft"], a: 3,
    why: "The lateral curve crosses the dashed average line near 300 ft on an 800 ft lateral, about 38% of the length as the text states. The conveyance pipe line crosses the average near 200 ft.",
    eq: null, calc: null, fig: "11.9", table: null },
  { id: "11-066", ch: 11, sec: "11.4", page: 221, type: "figure", level: 2,
    q: "In Figure 11.9, what are the approximate pressures at the far end of the 800 ft lateral and of the same pipe used as a conveyance pipe?",
    opts: ["About 25 psi for the lateral and 47 psi for the conveyance pipe", "About 47 psi for the lateral and 25 psi for the conveyance pipe", "About 50 psi for both", "About 60 psi for the lateral and 35 psi for the conveyance pipe"], a: 1,
    why: "Both start at 60 psi. The lateral curve flattens to about 47 psi because flow drops as sprinklers discharge, while the conveyance line falls straight to about 25 psi (35 psi loss).",
    eq: null, calc: null, fig: "11.9", table: null },
  { id: "11-067", ch: 11, sec: "11.4", page: 221, type: "recall", level: 2,
    q: "In the Figure 11.9 example, what fraction of the total lateral head loss occurs between the inlet and the point of average pressure?",
    opts: ["About 75%", "About 25%", "About 50%", "About 38%"], a: 0,
    why: "The book states about 75% of the loss occurs before the average-pressure point, which lies about 38% of the way along. That is why Pi = Pa + 0.75 Pl and Pd = Pa − 0.25 Pl.",
    eq: "11.5", calc: null, fig: null, table: null },
  { id: "11-068", ch: 11, sec: "11.4", page: 221, type: "calc", level: 2,
    q: "In Figure 11.9, a 3-inch conveyance pipe carrying 160 gpm for 800 ft loses about 35 psi. Using a multiple outlet factor of 0.37 for 20 sprinklers, what is the loss along the lateral?",
    opts: ["About 35 psi", "About 26 psi", "About 13 psi", "About 9 psi"], a: 2,
    why: "Lateral loss = F × conveyance loss = 0.37 × 35 = 12.9 psi, about 13 psi as the text states. 35 psi ignores the outlets, 26 psi is 0.75 × 35, and 9 psi is 0.25 × 35.",
    eq: "11.11", calc: "eq-11.11", fig: null, table: null },
  { id: "11-069", ch: 11, sec: "11.4", page: 221, type: "calc", level: 1,
    q: "A level lateral has an average pressure of 45 psi and a friction loss of 7 psi. What are the inlet and distal end pressures?",
    opts: ["50.3 psi at the inlet and 43.3 psi at the end", "48.5 psi at the inlet and 41.5 psi at the end", "52.0 psi at the inlet and 45.0 psi at the end", "43.3 psi at the inlet and 50.3 psi at the end"], a: 0,
    why: "Eq. 11.5: Pi = 45 + 0.75 × 7 = 50.3 psi. Eq. 11.6: Pd = 45 − 0.25 × 7 = 43.3 psi. 48.5 and 41.5 split the loss in half, 52.0 and 45.0 put the full loss above the average, and 43.3 at the inlet with 50.3 at the end swaps the ends.",
    eq: "11.5", calc: "eq-11.5-11.9", fig: null, table: null },
  { id: "11-070", ch: 11, sec: "11.4", page: 221, type: "calc", level: 1,
    q: "A lateral on level ground is designed for an average pressure of 40 psi. What is the maximum allowable friction loss along it?",
    opts: ["4 psi", "10 psi", "20 psi", "8 psi"], a: 3,
    why: "Eq. 11.7: Max Pl = 0.20 × Pa = 0.20 × 40 = 8 psi. 4 psi uses 10% (the discharge limit), 10 psi uses 25%, and 20 psi uses 50%.",
    eq: "11.7", calc: "eq-11.5-11.9", fig: null, table: null },
  { id: "11-071", ch: 11, sec: "11.4", page: 222, type: "calc", level: 3,
    q: "A 4-inch aluminum lateral (3.9 in inside diameter, C = 120) is 1,320 ft long with sprinklers every 40 ft discharging 8 gpm at an average 45 psi on level ground. Using F = 0.36, does it meet the pressure variation guideline?",
    opts: ["Yes. Friction loss is about 4.5 psi, under the 9 psi allowed", "No. Friction loss is about 34 psi, above the 9 psi allowed", "No. Friction loss is about 12.4 psi, above the 9 psi allowed", "Yes. Friction loss is about 8.9 psi, under the 9 psi allowed"], a: 2,
    why: "There are 1,320 ÷ 40 = 33 sprinklers, so Q = 264 gpm. Eq. 11.11 gives Pl = 4.56 × 0.36 × (264/120)^1.852 × 1,320 ÷ 3.9^4.866 = 12.4 psi. The limit is 0.20 × 45 = 9 psi, so it fails. 34 psi leaves out F, 4.5 psi applies F twice, and 8.9 psi is Example 11.4 with 220 gpm at 30 ft spacing.",
    eq: "11.11", calc: "eq-11.11", fig: null, table: null },
  { id: "11-072", ch: 11, sec: "11.4", page: 222, type: "calc", level: 3,
    q: "A lateral with an average pressure of 50 psi and friction loss of 10 psi runs downhill, with the inlet 20 ft above the distal end. What are the inlet and end pressures?",
    opts: ["57.5 psi at the inlet and 47.5 psi at the end", "53.2 psi at the inlet and 51.8 psi at the end", "61.8 psi at the inlet and 43.2 psi at the end", "48.8 psi at the inlet and 56.2 psi at the end"], a: 1,
    why: "Elevation term = 20 ÷ 2.31 = 8.66 psi. Eq. 11.8: Pi = 50 + 7.5 − 0.5 × 8.66 = 53.2 psi. Eq. 11.9: Pd = 50 − 2.5 + 4.33 = 51.8 psi. 57.5 and 47.5 ignore elevation, and 61.8 and 43.2 treat the lateral as uphill.",
    eq: "11.8", calc: "eq-11.5-11.9", fig: null, table: null },
  { id: "11-073", ch: 11, sec: "11.4", page: 222, type: "calc", level: 3,
    q: "A lateral with an average pressure of 50 psi and 6 psi of friction loss runs 15 ft uphill. What is the pressure variation and does it pass?",
    opts: ["About 6.0 psi (12% of average), which passes", "About 0.5 psi (1% of average), which passes", "About 12.5 psi (25% of average), which fails", "About 19 psi (38% of average), which fails"], a: 2,
    why: "With Ei − Ed = −15 ft, the elevation term is −6.49 psi. Pi = 50 + 4.5 + 3.25 = 57.7 psi and Pd = 50 − 1.5 − 3.25 = 45.3 psi, a 12.5 psi spread, which is 25% of 50 psi and exceeds 20%. 6 psi ignores elevation, and 0.5 psi treats the lateral as downhill.",
    eq: "11.9", calc: "eq-11.5-11.9", fig: null, table: null },
  { id: "11-074", ch: 11, sec: "11.4", page: 222, type: "concept", level: 2,
    q: "Why does a lateral that runs downhill usually have less pressure variation than the same lateral on level ground?",
    opts: ["Friction loss per foot is lower in pipe that slopes downward", "Gaining elevation head downhill offsets part of the friction loss", "Sprinklers on a downhill lateral discharge less water than on level ground", "Water moves more slowly in a downhill lateral, so less pressure is lost"], a: 1,
    why: "Each 2.31 ft of drop adds 1 psi, which makes up for friction along the pipe. In Example 11.4 the downhill case varied only 2.8 psi versus 8.9 psi on level ground. Friction itself does not depend on slope.",
    eq: "11.8", calc: "eq-11.5-11.9", fig: null, table: null },
  { id: "11-075", ch: 11, sec: "11.4", page: 222, type: "calc", level: 1,
    q: "A lateral is 1,200 ft long with sprinklers every 30 ft discharging 6 gpm each. What is the inflow to the lateral?",
    opts: ["240 gpm", "180 gpm", "200 gpm", "36 gpm"], a: 0,
    why: "Eq. 11.16: Qi = qs × L ÷ SL = 6 × 1,200 ÷ 30 = 240 gpm (40 sprinklers). 180 gpm uses 40 ft spacing, 200 gpm uses 36 ft, and 36 gpm divides incorrectly.",
    eq: "11.16", calc: "eq-11.16", fig: null, table: null },
  { id: "11-076", ch: 11, sec: "11.4", page: 222, type: "calc", level: 2,
    q: "Friction loss for full flow in a 1,200 ft lateral pipe is 2.0 psi/100 ft. With a multiple outlet factor of 0.36, what is the friction loss along the lateral?",
    opts: ["24.0 psi", "6.5 psi", "0.7 psi", "8.6 psi"], a: 3,
    why: "Conveyance loss = 2.0 × 1,200 ÷ 100 = 24.0 psi. Lateral loss = 0.36 × 24.0 = 8.6 psi, the method of Example 11.4. 24.0 psi ignores the outlets, 6.5 psi multiplies again by 0.75, and 0.7 psi forgets the length.",
    eq: "11.11", calc: null, fig: null, table: null },
  { id: "11-077", ch: 11, sec: "11.4", page: 223, type: "scenario", level: 2,
    q: "A dealer suggests putting pressure regulators on every sprinkler of a grower's lateral to fix uneven pressure. The grower asks what the catch is. What do you tell him?",
    opts: ["Regulators make discharge vary more from head to head, so heads near the main over-water even more", "Regulators only work on laterals that run downhill, so they will not help on level or rising ground", "Regulators lose pressure, so inlet pressure must rise, and they add cost. Use them only where pressure is high", "Regulators cannot be fitted to impact sprinklers, so every head would need to be a spray device"], a: 2,
    why: "Regulators hold nearly constant outlet pressure and give high uniformity, but water loses pressure passing through them, so inlet pressure must rise, and they add equipment and energy cost.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-078", ch: 11, sec: "11.4", page: 223, type: "figure", level: 2,
    q: "In Figure 11.10, the Hi-flo 30 regulator passes 10 gpm with 80 psi at its inlet. What is its outlet pressure?",
    opts: ["About 25 psi", "About 35 psi", "About 55 psi", "About 15 psi"], a: 0,
    why: "Above roughly 35 to 40 psi inlet, each flow curve is nearly flat. The 10 gpm curve sits near 24 to 25 psi across the inlet range. 35 psi and 55 psi would be no regulation, and 15 psi is on the rising part below the regulating range.",
    eq: null, calc: null, fig: "11.10", table: null },
  { id: "11-079", ch: 11, sec: "11.4", page: 223, type: "figure", level: 2,
    q: "From Figure 11.10, about what inlet pressure must the Hi-flo 30 regulator receive before it begins regulating?",
    opts: ["About 12 to 15 psi", "About 60 to 65 psi", "About 100 to 110 psi", "About 35 to 40 psi"], a: 3,
    why: "The curves rise steeply from about 12 psi and level off around 35 to 40 psi inlet. Below that, outlet pressure simply follows inlet pressure minus losses. 12 psi is where outlet pressure starts above zero.",
    eq: null, calc: null, fig: "11.10", table: null },
  { id: "11-080", ch: 11, sec: "11.4", page: 223, type: "figure", level: 2,
    q: "From the lower graph in Figure 11.10, at 100 psi how does a standard 5/32 in nozzle compare with the 5 gpm flow control nozzle (FCN)?",
    opts: ["They discharge about the same", "The standard nozzle puts out about 2 gpm more", "The standard nozzle puts out about 5 gpm more", "The FCN puts out about 1 gpm more"], a: 1,
    why: "At 100 psi the standard 5/32 in curve is near 7 gpm while the FCN curve is near 4.9 gpm. The curves cross at about 48 psi, where both give about 5 gpm.",
    eq: null, calc: null, fig: "11.10", table: null },
  { id: "11-081", ch: 11, sec: "11.4", page: 223, type: "concept", level: 2,
    q: "How do pressure compensating (flow control) nozzles compare with pressure regulators?",
    opts: ["They cost more than regulators but work over a much wider range of inlet pressures", "They raise the sprinkler discharge as pressure increases, the same as a standard nozzle", "They can cost less to buy and run but generally work over a narrower pressure range", "They need no inlet pressure above the design pressure, unlike a standard nozzle"], a: 2,
    why: "Flow control nozzles use a flexible orifice that closes at high pressure and opens at low pressure. They serve the same purpose as regulators at lower cost, but the book notes they generally have a smaller operating range.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-082", ch: 11, sec: "11.4", page: 222, type: "scenario", level: 3,
    q: "A grower says: \"My wheel line runs up a slope from the main, and the far end always looks dry.\" Which response best addresses it?",
    opts: ["Lengthen the set time so the far end catches up, since the dry heads just need more hours to apply the depth", "Measure inlet and end pressures. If variation tops 20% of average, lay the line on the contour or add regulators", "Put larger nozzles on the far-end sprinklers only, so they throw more water despite the lower pressure there", "Lower the pump pressure so the heads near the main stop over-watering and the whole line evens out"], a: 1,
    why: "Uphill laterals lose pressure to both friction and elevation, as in Example 11.4c where variation reached 41%. Checking pressures confirms the cause, and layout changes or regulation are the fixes. Longer sets over-water the inlet end, and lowering pressure starves the far end more.",
    eq: "11.9", calc: "eq-11.5-11.9", fig: null, table: null },
  { id: "11-083", ch: 11, sec: "11.4", page: 222, type: "scenario", level: 2,
    q: "A grower can lay a new lateral either up or down a uniform 2% grade from the mainline. Which do you recommend?",
    opts: ["Uphill, because the water moves more slowly and loses less to friction", "Uphill, because the inlet pressure needed at the mainline will be lower", "Either way, because slope does not change pressure variation on a lateral", "Downhill, because elevation gain offsets friction and keeps variation small"], a: 3,
    why: "In Example 11.4 the downhill lateral varied 2.8 psi and the uphill lateral 20.3 psi (41%). The book advises running laterals on the contour or downslope when possible.",
    eq: "11.8", calc: "eq-11.5-11.9", fig: null, table: null },
  { id: "11-084", ch: 11, sec: "11.4", page: 222, type: "scenario", level: 3,
    q: "A grower wants to replace his 5/32 in nozzles with 3/16 in nozzles at the same pressure to put on more water. What should you remind him to check?",
    opts: ["Flow rises about 44%, so recheck the application rate against the soil limit and the lateral friction loss", "Flow rises about 20%, the same as the diameter change, which is too small to affect anything else", "Flow will not change unless the pressure changes, so the larger nozzles will only widen the pattern", "Flow rises about 10%, the same as raising pressure 20%, so nothing else needs to be checked"], a: 0,
    why: "3/16 ÷ 5/32 = 1.2, and flow varies with D², so 1.2² = 1.44, a 44% increase. More flow raises Ar and the lateral inflow, which increases friction loss and may break the 20% pressure limit or the soil intake rate.",
    eq: "11.1", calc: "eq-11.1-ratio", fig: null, table: null },
  { id: "11-085", ch: 11, sec: "11.5", page: 223, type: "recall", level: 1,
    q: "What two conditions limit the maximum inflow to a sprinkler lateral?",
    opts: ["The pump horsepower and the size of the nozzles on the lateral", "The soil intake rate and the peak crop water use rate", "The mainline length and the number of laterals in the field", "The 20% pressure variation limit and the maximum water velocity"], a: 3,
    why: "Section 11.5 names two limits: friction must not push pressure variation above 20% of average, and velocity must stay below the limit that risks surge damage. The smaller resulting flow governs.",
    eq: "11.12", calc: null, fig: null, table: null },
  { id: "11-086", ch: 11, sec: "11.5", page: 224, type: "recall", level: 1,
    q: "What is the usual maximum water velocity in a sprinkler lateral?",
    opts: ["5 ft/s in all cases, the same limit used for mainlines and buried pipe", "7 ft/s, or up to 10 ft/s with slow filling and gradual valve closing", "3 ft/s, or up to 5 ft/s if the lateral is filled slowly at startup", "12 ft/s, because the sprinklers relieve any surge in the lateral"], a: 1,
    why: "The book gives 7 ft/s as the common limit and allows 10 ft/s with slow filling and gradual valve closing. 5 ft/s is the mainline guideline used in Chapter 12.",
    eq: "11.13", calc: "eq-11.10-11.13", fig: null, table: null },
  { id: "11-087", ch: 11, sec: "11.5", page: 224, type: "concept", level: 2,
    q: "Why can sprinkler laterals tolerate higher water velocities than mainlines?",
    opts: ["Laterals are always made of thicker, stronger pipe than mainlines in moved systems", "Flow in a lateral never exceeds 100 gpm, so surge pressures stay small", "Sprinklers along the lateral let high-pressure water and air escape before the pipe is damaged", "Laterals are drained after every set, so there is no trapped air to compress"], a: 2,
    why: "Open sprinklers act as relief points that vent water and air during surges. A mainline is closed along its length, so surges build higher.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-088", ch: 11, sec: "11.5", page: 224, type: "calc", level: 1,
    q: "Using Eq. 11.13, what is the maximum inflow for a lateral with a 3.9 in inside diameter at 10 ft/s?",
    opts: ["372 gpm", "260 gpm", "95 gpm", "3,719 gpm"], a: 0,
    why: "Qmax = 2.445 × 10 × 3.9² = 2.445 × 10 × 15.21 = 372 gpm. 260 gpm is the 7 ft/s value, 95 gpm uses D instead of D², and 3,719 gpm is a decimal slip.",
    eq: "11.13", calc: "eq-11.10-11.13", fig: null, table: null },
  { id: "11-089", ch: 11, sec: "11.5", page: 224, type: "calc", level: 3,
    q: "A 4-inch aluminum lateral (3.9 in inside diameter, C = 120) is 1,320 ft long with average pressure of 50 psi and F = 0.36. What is the maximum inflow, and which limit governs?",
    opts: ["About 235 gpm, set by the pressure variation limit", "About 260 gpm, set by the 7 ft/s velocity limit", "About 372 gpm, set by the 10 ft/s velocity limit", "About 495 gpm, the sum of the two separate limits"], a: 0,
    why: "Eq. 11.12 gives Qmax = [0.2 × 50 × 3.9^4.866 × 120^1.852 ÷ (4.56 × 0.36 × 1,320)]^(1/1.852) = 235 gpm. Eq. 11.13 at 7 ft/s gives 260 gpm. The smaller value, 235 gpm, governs, so friction controls on this long lateral.",
    eq: "11.12", calc: "eq-11.10-11.13", fig: null, table: null },
  { id: "11-090", ch: 11, sec: "11.5", page: 225, type: "calc", level: 2,
    q: "Using Figure 11.11, a 4-inch aluminum lateral 800 ft long at 50 psi average pressure has sprinklers every 40 ft. What is the maximum average sprinkler discharge?",
    opts: ["10.4 gpm", "13.0 gpm", "6.5 gpm", "18.6 gpm"], a: 1,
    why: "At 800 ft and 50 psi the 4-inch curve is still on the 260 gpm velocity plateau. There are 800 ÷ 40 = 20 sprinklers, so 260 ÷ 20 = 13.0 gpm. 10.4 gpm divides by 25 sprinklers, 6.5 gpm uses 40 sprinklers, and 18.6 gpm uses 14.",
    eq: "11.13", calc: "eq-11.10-11.13", fig: "11.11", table: null },
  { id: "11-091", ch: 11, sec: "11.5", page: 225, type: "figure", level: 2,
    q: "In the 40 psi panel of Figure 11.11, at about what lateral length does friction start to govern for the 3-inch pipe?",
    opts: ["About 830 ft", "About 1,100 ft", "About 200 ft", "About 600 ft"], a: 3,
    why: "The 3-inch curve leaves the 145 gpm plateau near 600 ft at 40 psi. About 830 ft is the 4-inch break and about 1,100 ft is the 5-inch break in that panel.",
    eq: null, calc: null, fig: "11.11", table: null },
  { id: "11-092", ch: 11, sec: "11.5", page: 225, type: "figure", level: 3,
    q: "From the 50 psi panel of Figure 11.11, what is the maximum inflow for a 4-inch lateral 1,400 ft long?",
    opts: ["About 260 gpm", "About 145 gpm", "About 230 gpm", "About 300 gpm"], a: 2,
    why: "In the 50 psi panel the 4-inch curve drops off the 260 gpm plateau near 1,070 ft and reads about 228 gpm at 1,400 ft. 260 gpm applies only to shorter laterals, and 145 gpm is the 3-inch plateau.",
    eq: null, calc: null, fig: "11.11", table: null },
  { id: "11-093", ch: 11, sec: "11.5", page: 225, type: "figure", level: 3,
    q: "From the 60 psi panel of Figure 11.11, up to about what length does the 5-inch lateral stay limited by velocity at 410 gpm?",
    opts: ["About 1,100 ft", "About 1,400 ft", "About 2,000 ft", "About 1,700 ft"], a: 3,
    why: "At 60 psi the 5-inch curve stays at 410 gpm until about 1,700 ft. Higher average pressure allows more friction loss, so the break moves right: about 1,100 ft at 40 psi and 1,400 ft at 50 psi.",
    eq: null, calc: null, fig: "11.11", table: null },
  { id: "11-094", ch: 11, sec: "11.5", page: 225, type: "concept", level: 3,
    q: "In Figure 11.11, why is the maximum inflow flat for short laterals and declining for long ones?",
    opts: ["Pressure variation governs short laterals, while velocity governs the long ones", "Velocity caps short laterals, while friction, growing with length, caps long ones", "Long laterals have more sprinklers, which reduce velocity and the allowed flow", "The Hazen-Williams C value of the pipe drops as the lateral gets longer"], a: 1,
    why: "Eq. 11.13 does not depend on length, so it caps flow at a constant value. Eq. 11.12 allows less flow as length increases, so beyond the break point it gives the smaller value.",
    eq: "11.12", calc: "eq-11.10-11.13", fig: "11.11", table: null },
  { id: "11-095", ch: 11, sec: "11.5", page: 224, type: "recall", level: 2,
    q: "At 7 ft/s, what maximum inflows does Figure 11.11 show for 5-inch, 4-inch and 3-inch aluminum laterals?",
    opts: ["410, 260 and 145 gpm", "500, 300 and 150 gpm", "428, 280 and 160 gpm", "350, 230 and 115 gpm"], a: 0,
    why: "The velocity plateaus in Figure 11.11 are 410, 260 and 145 gpm, computed from Eq. 11.13 with the pipe inside diameters.",
    eq: "11.13", calc: "eq-11.10-11.13", fig: "11.11", table: null },
  { id: "11-096", ch: 11, sec: "11.5", page: 225, type: "concept", level: 3,
    q: "Figure 11.11 was drawn for outlets 40 ft apart. Why can it still guide laterals with other outlet spacings?",
    opts: ["Outlet spacing has no effect on lateral friction loss at all, because F is the same for any number of outlets", "The chart already includes a correction for outlet spacing built into the 7 ft/s velocity line for each pipe size", "Velocity governs short laterals at any spacing, and once friction governs there are enough outlets that F barely changes", "Velocity is always the governing limit for aluminum laterals, so friction and outlet spacing never come into play"], a: 2,
    why: "On short laterals flow is set by velocity, which ignores spacing. When friction takes over, many sprinklers are on the line, and the multiple outlet factor F is close to its limiting value for any spacing.",
    eq: null, calc: null, fig: "11.11", table: null },
  { id: "11-097", ch: 11, sec: "11.5", page: 224, type: "calc", level: 3,
    q: "A 3-inch aluminum lateral (2.9 in inside diameter, C = 120, F = 0.36) is 1,200 ft long with an average pressure of 50 psi and sprinklers every 40 ft. What is the largest average sprinkler discharge it can supply?",
    opts: ["About 3.8 gpm", "About 4.8 gpm", "About 7.6 gpm", "About 5.0 gpm"], a: 0,
    why: "Eq. 11.12 gives about 114 gpm and Eq. 11.13 at 7 ft/s gives 144 gpm, so 114 gpm governs. With 1,200 ÷ 40 = 30 sprinklers, q = 114 ÷ 30 = 3.8 gpm. 4.8 gpm uses the velocity limit, and 7.6 gpm divides by 15.",
    eq: "11.12", calc: "eq-11.10-11.13", fig: null, table: null },
  { id: "11-098", ch: 11, sec: "11.5", page: 224, type: "scenario", level: 3,
    q: "A grower wants to run 12 gpm sprinklers every 40 ft on an existing 3-inch aluminum lateral 600 ft long. What do you tell him?",
    opts: ["That is 180 gpm, well within the 260 gpm limit for 3-inch pipe, so the plan works as is", "That is 120 gpm, within the 145 gpm limit for 3-inch pipe, so the plan works as is", "That is 180 gpm, over the 145 gpm limit for 3-inch pipe. Use 4-inch pipe or fewer or smaller heads", "Velocity does not matter on a lateral, because the sprinklers relieve any surge pressure"], a: 2,
    why: "There are 600 ÷ 40 = 15 sprinklers × 12 gpm = 180 gpm. Figure 11.11 caps 3-inch pipe at 145 gpm (7 ft/s). 260 gpm is the 4-inch limit. Sprinklers help, but a velocity limit still applies.",
    eq: "11.13", calc: "eq-11.10-11.13", fig: "11.11", table: null },
  { id: "11-099", ch: 11, sec: "11.5", page: 224, type: "calc", level: 3,
    q: "Example 11.5 found a 410 gpm limit for a 5-inch lateral. If that lateral were 1,320 ft long at 50 psi with sprinklers 40 ft apart, and Figure 11.11 still gives about 410 gpm, what is the maximum average sprinkler discharge?",
    opts: ["16.4 gpm", "10.3 gpm", "9.3 gpm", "12.4 gpm"], a: 3,
    why: "1,320 ÷ 40 = 33 sprinklers, so 410 ÷ 33 = 12.4 gpm. 16.4 gpm is the book's answer for the 1,000 ft lateral with 25 sprinklers, and 9.3 gpm divides by 44.",
    eq: "11.16", calc: "eq-11.10-11.13", fig: "11.11", table: null },
  { id: "11-100", ch: 11, sec: "11.6", page: 226, type: "recall", level: 1,
    q: "In moved-lateral design, why is the time of operation (To) shorter than the set time (Ts)?",
    opts: ["To includes the days of downtime for maintenance", "Part of each set is used to drain the lateral and move it", "To is the total time needed to irrigate the whole field", "Ts counts only the hours that the pump is actually running"], a: 1,
    why: "The book's example operates 10 hr of a 12 hr set, leaving time to drain and move the lateral. Downtime for maintenance is a separate term in days.",
    eq: "11.14", calc: "eq-11.14", fig: null, table: null },
  { id: "11-101", ch: 11, sec: "11.6", page: 226, type: "recall", level: 1,
    q: "In Eq. 11.14, what does the downtime Td represent?",
    opts: ["Hours each set spends draining before the lateral can be moved again", "Days for maintenance, moving laterals back to the start, and field work", "Days between rain events when no irrigation at all is needed", "Hours the pump is shut off each day for utility load control"], a: 1,
    why: "Td covers engine and system maintenance, preparing laterals for the next irrigation, and harvesting or other operations. Hours lost to draining each set are captured by Ts versus To.",
    eq: "11.14", calc: "eq-11.14", fig: null, table: null },
  { id: "11-102", ch: 11, sec: "11.6", page: 226, type: "calc", level: 1,
    q: "A field is 1,320 ft wide in the direction the lateral moves, and laterals are spaced 60 ft apart. How many sets are needed?",
    opts: ["26 sets", "33 sets", "44 sets", "22 sets"], a: 3,
    why: "Eq. 11.15: Ns = Wf ÷ Sm = 1,320 ÷ 60 = 22 sets. 26 sets uses 50 ft spacing, 33 sets uses 40 ft (the sprinkler spacing), and 44 sets doubles the field width.",
    eq: "11.15", calc: "eq-11.15", fig: null, table: null },
  { id: "11-103", ch: 11, sec: "11.6", page: 228, type: "calc", level: 2,
    q: "A field needs 30 sets of 12 hr each. The irrigation interval is 10 days and 2 days are needed for downtime. How many laterals are needed?",
    opts: ["1 lateral", "3 laterals", "2 laterals", "4 laterals"], a: 2,
    why: "Available days = 10 − 2 = 8, and two 12 hr sets fit per day, so one lateral covers 16 sets. 30 ÷ 16 = 1.9, rounded up to 2 laterals. One lateral would need 15 days.",
    eq: "11.14", calc: "proc-moved-lateral", fig: null, table: null },
  { id: "11-104", ch: 11, sec: "11.6", page: 228, type: "calc", level: 3,
    q: "A 1,320 ft square field uses a moved lateral with sprinklers 40 ft apart and 60 ft between sets. Gross capacity is 7 gpm/ac, sets are 12 hr with 11 hr of operation, the interval may not exceed 7 days, and 1 day of downtime is needed. Following Example 11.6, what minimum sprinkler discharge is required?",
    opts: ["About 5.5 gpm", "About 4.6 gpm", "About 10.9 gpm", "About 4.2 gpm"], a: 0,
    why: "Ns = 1,320 ÷ 60 = 22 sets. With 6 days available and 2 sets per day, one lateral handles 12 sets, so 2 laterals are needed, each doing 11 sets in 5.5 days, making the interval 6.5 days. qs = 7 × 40 × 60 ÷ 43,560 × (22/2) × (12/11) × (6.5/5.5) = 5.5 gpm. 4.6 gpm drops the Ii/(Ii − Td) term, 10.9 gpm uses one lateral, and 4.2 gpm drops both time ratios.",
    eq: "11.14", calc: "eq-11.14", fig: null, table: null },
  { id: "11-105", ch: 11, sec: "11.6", page: 228, type: "concept", level: 3,
    q: "In Example 11.6, why was the irrigation interval shortened from 10 to 8 days?",
    opts: ["Two laterals each needed only 6 days for 12 sets, plus 2 days of downtime", "Crop water use rose during the season, so a shorter interval was required", "The soil could only store enough water for 8 days of crop water use", "One lateral needed exactly 8 days to irrigate all 24 sets in the field"], a: 0,
    why: "With 24 sets and two laterals, each lateral does 12 sets at 2 per day, which takes 6 days. Adding 2 days of downtime gives 8 days, so the design uses 8 days in Eq. 11.14.",
    eq: "11.14", calc: "eq-11.14", fig: null, table: null },
  { id: "11-106", ch: 11, sec: "11.6", page: 226, type: "scenario", level: 2,
    q: "A designer finds that the inflow a grower's lateral would need (Eq. 11.16) exceeds the maximum allowable inflow from Section 11.5. What is the usual fix?",
    opts: ["Raise the pump pressure so the existing lateral can push the extra flow through", "Add another lateral and run longer sets or shorter laterals so each line carries less flow", "Put on larger nozzles so each set finishes sooner and the lateral is busy less of the time", "Spread the sprinklers farther apart on the lateral without changing the nozzles"], a: 1,
    why: "The book says excessive inflow is generally solved with more laterals, longer set times or shorter laterals, which lowers the flow each lateral must carry. Larger nozzles raise inflow further.",
    eq: "11.16", calc: "eq-11.16", fig: null, table: null },
  { id: "11-107", ch: 11, sec: "11.6", page: 227, type: "figure", level: 1,
    q: "In Figure 11.12, how is the area irrigated per set defined?",
    opts: ["Sprinkler spacing SL times Sm", "Field width times field length", "Lateral length times the sprinkler spacing SL", "Lateral length times the lateral spacing Sm"], a: 3,
    why: "The hatched strip is one set: the full lateral length by one move distance Sm. SL × Sm is the area for one sprinkler, not a whole set.",
    eq: null, calc: null, fig: "11.12", table: null },
  { id: "11-108", ch: 11, sec: "11.6", page: 227, type: "concept", level: 2,
    q: "On a sloping field, how should a moved-lateral system generally be laid out?",
    opts: ["Mainline across the slope, with laterals running uphill from it to the top of the field", "Mainline and laterals both laid on the contour, with the pump at the highest point", "Mainline up and down the slope, with laterals across the slope so they are nearly level", "Laterals running uphill from the mainline so gravity helps drain them between sets"], a: 2,
    why: "Keeping laterals level limits pressure variation along them, while the mainline can absorb the elevation change. If a lateral must slope, running it downhill is better.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-109", ch: 11, sec: "11.6", page: 226, type: "recall", level: 2,
    q: "What units does the gross system capacity Qc carry in Eq. 11.14, and where does it come from?",
    opts: ["in/hr, from the soil intake rate and the maximum rates listed in Table 11.4", "gpm per sprinkler, read from Table 11.1 for the nozzle and design pressure", "gpm/ac, from the net capacity requirement and application efficiency in Chapter 5", "acre-inches per day, from the water right and the number of irrigated acres"], a: 2,
    why: "Qc is gpm per acre computed from the net system capacity requirement and the application efficiency. The 43,560 in Eq. 11.14 converts the SL × Sm area to acres.",
    eq: "11.14", calc: "eq-11.14", fig: null, table: null },
  { id: "11-110", ch: 11, sec: "11.6", page: 228, type: "scenario", level: 3,
    q: "A grower has one wheel line and 22 sets of 12 hr each on his field. His crop needs water every 8 days. Can he keep up?",
    opts: ["Yes. 22 sets × 12 hr is 264 hr, which fits easily inside an 8-day interval with time to spare", "No. One line needs 11 days at 2 sets per day, so he needs a second line or a different schedule", "Yes, as long as he applies a larger depth at each set so the crop can go longer between irrigations", "No, and a second line will not help because 22 sets cannot be split evenly between two lines"], a: 1,
    why: "Two 12 hr sets per day means 22 sets take 11 days, longer than the 8-day interval. 264 hr is 11 days, not less than 8. A second line (11 sets each, 5.5 days) fits. A larger depth does not shorten the rotation.",
    eq: "11.15", calc: "proc-moved-lateral", fig: null, table: null },
  { id: "11-111", ch: 11, sec: "11.6", page: 229, type: "scenario", level: 3,
    q: "A grower asks: \"Why does the sprinkler discharge in Eq. 11.14 go up when I take more downtime each rotation?\" What is the explanation?",
    opts: ["Downtime adds to the area that must be covered, so the field size term in the equation rises", "Downtime lowers the application efficiency, so more gross water is needed at each set", "More downtime means each lateral must cover more sets, so the Ns ÷ Nl term rises", "The same water must go on in fewer operating days, so the factor Ii ÷ (Ii − Td) rises"], a: 3,
    why: "Gross capacity is a 24-hour, every-day rate. If Td days are lost, the remaining Ii − Td days must deliver the whole interval's water, so discharge rises by Ii ÷ (Ii − Td). The same logic gives the Ts ÷ To factor for hours lost to moving.",
    eq: "11.14", calc: "eq-11.14", fig: null, table: null },
  { id: "11-112", ch: 11, sec: "11.7", page: 228, type: "recall", level: 1,
    q: "During an advective freeze, what can sprinkler irrigation do?",
    opts: ["Very little, and wetting foliage can cool plants and add to the damage", "Full protection at any wind speed, as long as the rate is high enough", "Protection only if the irrigation water is warmer than about 50°F", "Protection at any temperature if water is applied at 0.1 in/hr"], a: 0,
    why: "In an advective freeze, cold air and wind remove heat. The book says irrigation can do little, and evaporation from wet foliage can make damage worse, with ice loads damaging plants and equipment.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-113", ch: 11, sec: "11.7", page: 228, type: "recall", level: 1,
    q: "Under what conditions does a radiant frost occur?",
    opts: ["Cloudy, windy nights, when a mass of cold air moves in from another region", "Clear, calm, dry nights, when plants radiate energy and cool below air temperature", "Humid, foggy nights, when water vapor condenses on leaves and freezes", "Any night when the dew point stays above the freezing point of water"], a: 1,
    why: "Radiant frost happens on clear, calm, dry nights. Plants radiate energy to the sky and cool 1 to 4°F below air temperature even when air is above the critical value.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-114", ch: 11, sec: "11.7", page: 229, type: "recall", level: 1,
    q: "At what temperatures are leaves, blossoms and young fruit frequently killed?",
    opts: ["32 to 34°F", "20 to 24°F", "15 to 18°F", "26 to 30°F"], a: 3,
    why: "The book states the most sensitive tissues are frequently killed between 26 and 30°F, with hardier parts depending on stage of development.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-115", ch: 11, sec: "11.7", page: 229, type: "recall", level: 1,
    q: "About how much energy does evaporating one gram of water require?",
    opts: ["About 585 calories", "About 80 calories", "About 1 calorie", "About 5,850 calories"], a: 0,
    why: "Evaporation takes about 585 cal/g. Cooling liquid water releases only 1 calorie per gram per °C, which is why large amounts of water are needed if only cooling is relied on.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-116", ch: 11, sec: "11.7", page: 229, type: "concept", level: 2,
    q: "How does continuous sprinkling protect plant tissue during a radiant frost?",
    opts: ["The water layer insulates the plant from cold air by blocking wind and radiation", "Warm irrigation water heats the plant tissue directly to well above 40°F", "Freezing water on the plant releases heat of fusion, holding the film near 32°F", "Evaporation from the wet leaves releases heat that keeps the tissue warm"], a: 2,
    why: "As the film freezes it releases heat, keeping the coated tissue near 32°F while liquid water remains in contact with the ice. Evaporation does the opposite and cools plants. Water temperature alone contributes only 1 cal per gram per °C.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-117", ch: 11, sec: "11.7", page: 229, type: "concept", level: 2,
    q: "Why can light sprinkling that only wets the canopy damage a crop during frost?",
    opts: ["The water raises the dew point of the air above freezing, which forms frost on every leaf", "Evaporation from wet plant surfaces draws heat from the plants, cooling them below air temperature", "Wet leaves radiate more energy to the night sky than dry leaves, so they cool faster", "Ice forms too slowly on lightly wetted leaves to release any heat to the tissue"], a: 1,
    why: "If droplets reach plants and then evaporate rather than freeze, each gram removes about 585 calories from the plant. Protection needs freezing and condensation to outpace evaporation, which takes enough water applied often enough.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-118", ch: 11, sec: "11.7", page: 229, type: "recall", level: 2,
    q: "What overtree frost protection rates are most practical, and how often must foliage be rewetted?",
    opts: ["0.5 to 1.0 in/hr, with rewetting every 10 minutes", "0.01 to 0.05 in/hr, with rewetting every hour", "0.1 to 0.3 in/hr, with rewetting every 15 minutes", "0.1 to 0.3 in/hr, with rewetting once each minute"], a: 3,
    why: "The book gives 0.1 to 0.3 in/hr as most practical and says foliage must be rewetted once each minute so ice always stays in contact with liquid water.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-119", ch: 11, sec: "11.7", page: 229, type: "recall", level: 2,
    q: "When should overtree sprinkling for frost protection begin?",
    opts: ["When the dry bulb air temperature first falls to 32°F during the night", "When frost is first seen forming on leaves and blossoms at canopy height", "When the wet bulb temperature falls to 4°F above the lethal temperature", "When the dew point temperature falls to the lethal temperature of the tissue"], a: 2,
    why: "Sprinkling must start by the time the wet bulb temperature is 4°F above the lethal temperature, because starting causes evaporative cooling. It should continue until the wet bulb is back above the lethal temperature by about 4°F.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-120", ch: 11, sec: "11.7", page: 230, type: "recall", level: 2,
    q: "What is typical of undertree frost protection systems described in the chapter?",
    opts: ["Small 5/64 to 3/32 in nozzles, under 7° trajectory, 40 to 50 psi, 0.08 to 0.12 in/hr", "Large gun sprinklers at about 100 psi applying 0.5 in/hr over the whole block", "Overtree impact heads rated 0.3 in/hr mounted on short risers under the canopy", "Drip emitters run continuously at about 1 gph per tree through the frost night"], a: 0,
    why: "The book reports most undertree systems use small, low-trajectory heads at 40 to 50 psi applying 0.08 to 0.12 in/hr, a bit more than half of overtree rates, with air warming of about 2°F.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-121", ch: 11, sec: "11.7", page: 229, type: "table", level: 1,
    q: "From Table 11.5, what sprinkling rate is needed for a dry leaf temperature of 24°F with wind of 5 to 8 mph?",
    opts: ["0.2 in/hr", "0.3 in/hr", "0.4 in/hr", "0.5 in/hr"], a: 1,
    why: "The 24°F row gives 0.1, 0.2, 0.3, 0.4 and 0.8 in/hr for the five wind classes, so 5 to 8 mph is 0.3 in/hr. 0.2 is 2 to 4 mph and 0.4 is 10 to 14 mph.",
    eq: null, calc: "tab-11.5", fig: null, table: "11.5" },
  { id: "11-122", ch: 11, sec: "11.7", page: 229, type: "table", level: 1,
    q: "From Table 11.5, what sprinkling rate is needed for a 20°F dry leaf temperature with wind of 10 to 14 mph?",
    opts: ["0.8 in/hr", "0.6 in/hr", "0.3 in/hr", "0.4 in/hr"], a: 0,
    why: "The 20°F row reads 0.2, 0.3, 0.6 and 0.8 in/hr for 0 to 1, 2 to 4, 5 to 8 and 10 to 14 mph. 0.6 in/hr is the 5 to 8 mph value.",
    eq: null, calc: "tab-11.5", fig: null, table: "11.5" },
  { id: "11-123", ch: 11, sec: "11.7", page: 229, type: "table", level: 2,
    q: "Table 11.5 shows no rate for an 18°F dry leaf temperature with wind of 10 to 14 mph. What does that mean?",
    opts: ["Any sprinkling rate will work there, so no value needs to be listed", "The required rate is the same as for the 0 to 1 mph wind column", "Sprinkling is not expected to protect plants under those conditions", "Those conditions were not tested, but 0.1 in/hr is known to be safe"], a: 2,
    why: "Blank cells appear at cold temperatures and high wind, where sprinkling cannot supply heat fast enough. That matches the book's warning that windy, advective conditions defeat sprinkling.",
    eq: null, calc: "tab-11.5", fig: null, table: "11.5" },
  { id: "11-124", ch: 11, sec: "11.7", page: 230, type: "table", level: 3,
    q: "From Table 11.6, for buds with a critical temperature of 28°F and a dewpoint of 20°F, what is the minimum air temperature to turn the system on, and what does the footnote recommend?",
    opts: ["31°F minimum, and starting right at 31°F with no added margin", "35°F minimum, and starting 2 to 3°F lower, about 32 to 33°F", "28°F, the critical temperature itself, as both the minimum and the start", "33°F minimum, and starting 2 to 3°F higher, about 35 to 36°F"], a: 3,
    why: "A 20°F dewpoint falls in the 19 to 23°F range for 28°F critical, which gives 33°F. The footnote says this is an absolute minimum and recommends 2 to 3°F higher.",
    eq: null, calc: "tab-11.6", fig: null, table: "11.6" },
  { id: "11-125", ch: 11, sec: "11.7", page: 230, type: "table", level: 2,
    q: "From Table 11.6, what minimum turn-on air temperature is listed for a 32°F critical temperature with a 12°F dewpoint?",
    opts: ["45°F", "41°F", "37°F", "43°F"], a: 3,
    why: "The 32°F critical rows give 45, 43, 41, 39, 37, 35 and 33°F for dewpoints of 3 to 10, 10 to 16, 16 to 21, 21 to 24, 24 to 28, 28 to 31 and 31 to 32°F. A 12°F dewpoint gives 43°F.",
    eq: null, calc: "tab-11.6", fig: null, table: "11.6" },
  { id: "11-126", ch: 11, sec: "11.7", page: 230, type: "concept", level: 3,
    q: "Why does Table 11.6 require a higher turn-on air temperature when the dewpoint is low?",
    opts: ["A low dewpoint means the irrigation water coming from the well is colder than usual", "Dry air makes wet surfaces cool by evaporation when sprinkling starts, so it must begin earlier", "Air with a low dewpoint holds more heat, so less margin is needed before starting", "A low dewpoint means the wind is stronger, so an advective freeze is more likely"], a: 1,
    why: "With dry air the wet bulb temperature sits well below the air temperature. Starting sprinklers drives evaporative cooling toward the wet bulb, so the system must start while the air is still warm enough to keep tissue above the critical value.",
    eq: null, calc: "tab-11.6", fig: null, table: "11.6" },
  { id: "11-127", ch: 11, sec: "11.7", page: 229, type: "concept", level: 2,
    q: "According to the Table 11.5 footnote, how does the dry leaf temperature relate to air temperature?",
    opts: ["Equal to the air temperature on all nights, because leaves have very little mass", "About 10°F below the air temperature on any clear night, whatever the wind", "About 1°F below air temperature in light wind, and 3 to 4°F below on very calm nights", "Higher than the air temperature, because leaves store heat from the day"], a: 2,
    why: "The footnote defines the dry leaf temperature as the expected minimum of an unprotected leaf, from 1°F below air temperature with light wind to 3 to 4°F below on very calm nights.",
    eq: null, calc: "tab-11.5", fig: null, table: "11.5" },
  { id: "11-128", ch: 11, sec: "11.7", page: 230, type: "scenario", level: 3,
    q: "An orchard solid-set system has 12 gpm sprinklers on 40 ft × 60 ft spacing and 25 laterals on an automatic controller. The grower expects a 24°F dry leaf temperature with 6 mph wind and wants to cycle laterals for frost protection. What do you advise?",
    opts: ["Run all laterals at once. 0.48 in/hr exceeds the 0.3 in/hr needed, but cycling 25 laterals cannot rewet trees every minute", "Cycle the laterals one at a time. 0.48 in/hr is well above the 0.3 in/hr needed, so each block gets plenty of water", "Add more heads first. 0.48 in/hr is below the 0.8 in/hr needed at 24°F, so the system cannot protect the orchard", "Do not sprinkle at all. Table 11.5 gives no rate for a 6 mph wind, so sprinkling will not protect at these conditions"], a: 0,
    why: "Ar = 96.3 × 12 ÷ 2,400 = 0.48 in/hr, above the 0.3 in/hr in Table 11.5 for 24°F and 5 to 8 mph. But protection needs continuous rewetting about once a minute, so the whole block must run together, which requires a water supply for all 25 laterals. Also warn about ice loads on limbs.",
    eq: "11.2", calc: "tab-11.5", fig: null, table: "11.5" },
  { id: "11-129", ch: 11, sec: "11.7", page: 230, type: "scenario", level: 2,
    q: "A grower shut off his overtree frost sprinklers at sunrise when the air reached 33°F, while the trees were still coated with ice. Buds were damaged afterward. What should he have done?",
    opts: ["Keep sprinkling until the ice melted off the trees as the air warmed", "Shut the system off earlier, well before sunrise, to save water", "Switch over to undertree sprinklers at sunrise until the ice was gone", "Shut off as soon as the dew point rose to 32°F, whatever the ice"], a: 0,
    why: "Melting ice absorbs heat, and once water stops, evaporation and melting draw heat from the buds. The book says sprinkling usually must continue until ice completely melts the next morning.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-130", ch: 11, sec: "11.7", page: 228, type: "scenario", level: 2,
    q: "Forecast calls for a cold front with 15 mph winds and air temperatures falling to 22°F. A grower plans to run overtree sprinklers all night. What do you tell him?",
    opts: ["Run 0.1 in/hr all night. Table 11.5 shows that rate protects the crop at any wind speed and temperature", "This is an advective freeze. Sprinkling may add ice load and evaporative cooling without protecting the crop", "Turn the sprinklers on only after the air reaches 22°F, so the water freezes as soon as it lands", "Wind does not matter here, because 55°F groundwater carries enough heat to protect the crop"], a: 1,
    why: "Cold air moving in with wind is an advective freeze, where the book says irrigation can do little and may increase damage and ice loading. Table 11.5 rates climb steeply with wind, and warm groundwater supplies little heat.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-131", ch: 11, sec: "11.7", page: 231, type: "concept", level: 2,
    q: "According to the chapter, what matters most for successful frost protection with sprinklers?",
    opts: ["The total volume of water applied over the whole frost season", "Using the same set times and sequence as for ET irrigation", "The rate and timing of application, more than the total volume", "Applying water only after frost has visibly formed on plants"], a: 2,
    why: "The book states the rate and timing of application are often more important than the volume. Protection depends on continuous wetting at a sufficient rate from start to ice melt.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-132", ch: 11, sec: "11.8", page: 231, type: "concept", level: 1,
    q: "Which two sprinkler performance properties does the summary call key, and what do they depend on?",
    opts: ["Riser height and lateral length, both set by the crop height and field", "Application efficiency and set time, both set by labor and soil", "Pipe material and C value, both set by the cost of the system", "Nozzle discharge and wetted diameter, both set by pressure and nozzle size"], a: 3,
    why: "The summary names the flow rate from the nozzle and the diameter wetted by the sprinkler as key parameters, both controlled by pressure and nozzle diameter.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-133", ch: 11, sec: "11.4", page: 221, type: "concept", level: 2,
    q: "Sprinkler systems are designed by selecting the nozzle for which pressure along the lateral?",
    opts: ["The pressure at the lateral inlet end", "The pressure at the distal end", "The average pressure along the lateral", "The discharge pressure at the pump"], a: 2,
    why: "The book says nozzles are usually chosen for the average pressure, and then pressures at the ends are computed with Eqs. 11.5 and 11.6. Sprinklers above and below average then balance around the design flow.",
    eq: "11.5", calc: "eq-11.5-11.9", fig: null, table: null },
  { id: "11-134", ch: 11, sec: "11.4", page: 221, type: "recall", level: 2,
    q: "What does the multiple outlet factor F represent for a sprinkler lateral?",
    opts: ["The fraction of the sprinklers on the lateral that are part-circle heads at the ends", "The ratio of lateral friction loss to the loss in the same pipe carrying full inflow its whole length", "The ratio of the average pressure along the lateral to the inlet pressure at the mainline", "The fraction of the applied water that is lost to evaporation and drift along the lateral"], a: 1,
    why: "Because flow decreases as sprinklers discharge, a lateral loses only a fraction F of a conveyance pipe's loss, about 0.37 for 20 outlets and about 0.36 for 30 or more (Table 8.3).",
    eq: "11.11", calc: "eq-11.11", fig: null, table: null },
  { id: "11-135", ch: 11, sec: "11.4", page: 222, type: "recall", level: 2,
    q: "In Example 11.4, what was the pressure variation for the lateral on level ground compared with the allowed value?",
    opts: ["8.9 psi, which is 17.8% of 50 psi and within the limit", "20.3 psi, which is 41% of 50 psi and over the limit", "2.8 psi, which is 5.6% of 50 psi and within the limit", "12.4 psi, which is 25% of 50 psi and over the limit"], a: 0,
    why: "On level ground Pi = 56.7 psi and Pd = 47.8 psi, a variation of 8.9 psi or 17.8% of 50 psi. 2.8 psi is the downhill case and 20.3 psi the uphill case.",
    eq: "11.5", calc: "eq-11.5-11.9", fig: null, table: null },
  { id: "11-136", ch: 11, sec: "11.3", page: 214, type: "concept", level: 1,
    q: "Why does the book recommend using manufacturer data rather than Tables 11.1 and 11.2 for a specific system?",
    opts: ["They are for metric nozzle sizes only and must be converted first", "They list only spray heads, not impact sprinklers with straight bores", "They assume a 10 mph wind, which overstates the diameter in calm air", "They show typical values, and specific nozzles and sprinkler bodies vary"], a: 3,
    why: "Tables 11.1 and 11.2 represent typical straight bore nozzles on 23° impact sprinklers. Body design, nozzle type and riser height change discharge and throw, so the relevant manufacturer's data should be used.",
    eq: null, calc: null, fig: null, table: "11.1" },
  { id: "11-137", ch: 11, sec: "11.7", page: 230, type: "concept", level: 2,
    q: "Why can undertree sprinkling raise air temperature among the trees?",
    opts: ["The sprinklers push warm air up through the canopy like a wind machine", "Droplets cool and freeze, releasing heat, and humidity cuts outgoing radiation", "The wet ground absorbs the water and stops radiating heat to the sky", "Undertree systems use water heated at the pump before it reaches the heads"], a: 1,
    why: "In the misting zone, water gives up heat as it cools and freezes, humidity rises, and humid air has lower emissivity, which reduces radiative loss. Air temperature gains of about 2°F, up to 4°F, are reported.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-138", ch: 11, sec: "11.7", page: 230, type: "concept", level: 3,
    q: "Why might a sprinkler system designed for ET not be adequate for frost protection?",
    opts: ["ET systems apply water far too slowly for any frost use, even when every set runs at once", "ET systems always run at too high a pressure, which makes the drops too fine for frost use", "Frost work needs the whole block wetted at once, more capacity than an ET system rotating sets", "Frost protection needs larger droplets than an ET system can produce at any pressure"], a: 2,
    why: "ET systems move water through sets over days, while frost protection requires every plant rewetted continuously, so all sets run simultaneously. The book notes some cases need a second system with a different design.",
    eq: null, calc: null, fig: null, table: null },
  { id: "11-139", ch: 11, sec: "11.5", page: 224, type: "calc", level: 2,
    q: "A 5-inch aluminum lateral has an inside diameter of 4.856 in. What is the maximum inflow at 7 ft/s from Eq. 11.13?",
    opts: ["About 404 gpm", "About 428 gpm", "About 83 gpm", "About 577 gpm"], a: 0,
    why: "Qmax = 2.445 × 7 × 4.856² = 2.445 × 7 × 23.58 = 404 gpm. 428 gpm uses the 5 in nominal size, 83 gpm uses D instead of D², and 577 gpm uses 10 ft/s.",
    eq: "11.13", calc: "eq-11.10-11.13", fig: null, table: null },
  { id: "11-140", ch: 11, sec: "11.4", page: 224, type: "calc", level: 2,
    q: "A 4-inch lateral (3.9 in inside diameter, C = 120) is 1,000 ft long, carries 200 gpm and has F = 0.36. What is the friction loss along it from Eq. 11.11?",
    opts: ["About 15.6 psi", "About 4.2 psi", "About 1.4 psi", "About 5.6 psi"], a: 3,
    why: "Pl = 4.56 × 0.36 × (200/120)^1.852 × 1,000 ÷ 3.9^4.866 = 5.6 psi. 15.6 psi omits F, 4.2 psi multiplies by 0.75, and 1.4 psi multiplies by 0.25.",
    eq: "11.11", calc: "eq-11.11", fig: null, table: null }
]);
